import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"第一阶段 · 最小完整 MVP","description":"交付一个可以每天使用的最小完整产品。","frontmatter":{"title":"第一阶段 · 最小完整 MVP","description":"交付一个可以每天使用的最小完整产品。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-1.md","filePath":"delivery/stage-1.md","lastUpdated":1793761874000}'),l={name:"delivery/stage-1.md"};function i(o,t,h,s,n,_){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="第一阶段-·-最小完整-mvp" tabindex="-1">第一阶段 · 最小完整 MVP <a class="header-anchor" href="#第一阶段-·-最小完整-mvp" aria-label="Permalink to &quot;第一阶段 · 最小完整 MVP&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>第一阶段交付一个可以在真实浏览器里每天使用的最小完整产品。它只服务一个窄任务族，但必须走完“创建任务—执行—审批—查看产物—失败恢复”的完整路径。这个阶段不追求覆盖所有工作，只追求让第一条真实链路可靠可用。</p><p>本阶段分为四个小阶段：</p><table tabindex="0"><thead><tr><th>小阶段</th><th>目标</th></tr></thead><tbody><tr><td><a href="/hearth-os/delivery/stage-1/1-1.html">1.1 明确首个场景与真实任务</a></td><td>确定首个用户、任务族、非目标和验收任务。</td></tr><tr><td><a href="/hearth-os/delivery/stage-1/1-2.html">1.2 做出完整体验原型</a></td><td>用可点击原型走通任务、审批、产物和恢复。</td></tr><tr><td><a href="/hearth-os/delivery/stage-1/1-3.html">1.3 打通最小任务闭环</a></td><td>让任务能真实执行、审批、产出结果并在失败后恢复。</td></tr><tr><td><a href="/hearth-os/delivery/stage-1/1-4.html">1.4 用真实任务验收 MVP</a></td><td>让首位用户不依赖开发者也能独立使用。</td></tr></tbody></table><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>先选定首个用户和首个任务族，并用真实任务确定验收标准。</li><li>用可点击原型把完整路径和所有关键状态走一遍。</li><li>打通真实任务闭环，包括执行、审批、产物和失败恢复。</li><li>让首位用户连续使用一周，用真实任务验收 MVP。</li></ol>',7)])])}const m=e(l,[["render",i]]);export{p as __pageData,m as default};
